      let nome = null, max = 0;
      for (const f of r.querySelectorAll("font")) {
        const m = /font-size:\s*(\d+)%/i.exec(f.getAttribute("style") || "");
        if (m && Number(m[1]) > max) { max = Number(m[1]); nome = f; }
      }
      const t = (nome?.textContent || "").replace(/\s+/g, " ").trim();
      if (pareNome(t)) return t;
