    const prec = { ...a.membri };   // (la riga di prima, se la lista di adesso è filtrata)
    if (intera) for (const [ep, v] of Object.entries(a.membri)) if (v?.k === testa.k) { delete a.membri[ep]; usciti.add(ep); membri += attivi.has(ep); }
